# download the data file(s)
for file in files:
    idx = file.rfind("/")
    if (idx > 0):
        ofile = file[idx+1:]
    else:
        ofile = file

    response = requests.get("https://osdf-director.osg-htc.org/ncar/gdex/d640002/" + file)
    with open(ofile, "wb") as f:
        f.write(response.content)
